use vstd::prelude::*;

verus! {
    /// In‐place replace negative entries by 0, leave non‐negatives unchanged.
    ///
    /// Post‐condition:
    ///   1. The length is unchanged.
    ///   2. For every valid index j,
    ///        if old(a@)[j] < 0 then a[j] == 0
    ///        else                  a[j] == old(a@)[j].
    fn zap_negatives(a: &mut Vec<i32>)
        ensures
            // length unchanged
            a.len() == old(a.len()),
        ensures
            // every entry “zapped” if it was negative in the old vector
            forall|j: usize| j < a.len() ==>
                a[j] == if old(a@)[j] < 0 { 0 } else { old(a@)[j] }
    {
        let n = a.len();
        let mut i: usize = 0;
        while i < n
            invariant
                // 0 <= i <= n
                i <= n,
                // for all positions before i, we've already applied the rule
                forall|j: usize| j < i ==>
                    a[j] == if old(a@)[j] < 0 { 0 } else { old(a@)[j] },
                // for all positions at or after i, they still agree with old(a@)
                forall|j: usize| i <= j && j < n ==>
                    a[j] == old(a@)[j],
            decreases n - i
        {
            if a[i] < 0 {
                a[i] = 0;
            }
            i += 1;
        }
    }
}

fn main() {
    // Example usages / simple smoke‐tests
    let mut v1 = Vec::from_slice(&[-3, 0, 5, -1, 7]);
    zap_negatives(&mut v1);
    assert!(v1 == Vec::from_slice(&[0, 0, 5, 0, 7]));

    let mut v2: Vec<i32> = Vec::new();
    zap_negatives(&mut v2);
    assert!(v2.is_empty());
}